VALUES ('BIO-015', 'Avoid prolonged boiling of water-soluble vitamins', 'bioavailability', 'processing', 'vitamin C/folate-rich vegetables', 'ING_VITC_FOLATE_VEG', 'vitamin C and folate retention', 'NUT_VITC_FOLATE', 'Use steaming, microwaving, or brief cooking with minimal water', 'PROC_GENTLE_COOK', 'Water-soluble vitamins can leach into cooking water and degrade with heat/time', 'When vitamin C or folate is the target, prefer brief low-water methods or retain cooking liquid in the dish.', 'This is nutrient retention, not absorption enhancement; balance against food safety and desired texture.', 'general', 'A', 'USDA nutrient-retention research and reviews support method-dependent losses of water-soluble vitamins.', 'recipe_safe', 'USDA Table of Nutrient Retention Factors', 'government data', 'https://www.ars.usda.gov/ARSUserFiles/80400525/Data/retn/retn06.pdf', '2026-09-17', TRUE)
