VALUES ('GLY-001', 'Choose lower-GI carbohydrate forms', 'glycemic', 'ingredient substitution', 'refined or rapidly digested carbohydrate', 'CARB_REFINED', 'postprandial glucose', 'OUT_PPG', 'Swap toward intact whole grains, legumes, or minimally processed starches', 'SUB_LOW_GI', 'Particle size, starch structure, fiber, and food matrix slow digestion', 'Use within cultural preference, allergies, budget, and recipe identity; preserve serving context.', 'GI varies by variety, ripeness, processing, cooking, and mixed meal; do not use a single database value as universal.', 'general; diabetes requires individualized plan', 'A', 'Systematic reviews support low-GI dietary patterns for glycemic outcomes.', 'recipe_safe', 'Effect of low glycaemic index or load dietary patterns on glycaemic control in diabetes', 'systematic review/meta-analysis', 'https://pubmed.ncbi.nlm.nih.gov/34386719/', '2026-09-17', TRUE)
