VALUES ('GLY-002', 'Add soluble/viscous fiber', 'glycemic', 'ingredient+macro', 'carbohydrate-containing meal', 'MACRO_CARB', 'postprandial glucose', 'OUT_PPG', 'Add legumes, oats, barley, okra, chia, flax, or psyllium-compatible ingredients', 'ADD_VISCOUS_FIBER', 'Viscosity slows gastric emptying and glucose diffusion/absorption', 'Prefer whole-food additions; increase gradually and preserve hydration guidance.', 'Fiber type matters; avoid abrupt high doses in users with GI conditions without review.', 'general', 'A', 'Meta-analyses of viscous fiber show improved glycemic control and reduced postprandial response.', 'recipe_safe', 'Viscous fiber supplementation and glycemic control', 'systematic review/meta-analysis', 'https://pubmed.ncbi.nlm.nih.gov/30617143/', '2026-09-17', TRUE)
