VALUES ('GLY-005', 'Vegetables/protein before starch', 'glycemic', 'behavior', 'mixed meal with starch', 'MEAL_MIXED', 'postprandial glucose', 'OUT_PPG', 'Eat non-starchy vegetables and protein before the carbohydrate portion', 'SEQ_VEG_PROTEIN_FIRST', 'Food order alters gastric emptying and nutrient delivery', 'Add a serving instruction; do not restructure recipe ingredients unless components can remain distinct.', 'Evidence comes from small acute trials; long-term outcome evidence is limited.', 'general; type 2 diabetes', 'B', 'Randomized crossover trials show lower post-meal glucose when carbohydrate is eaten last.', 'instruction_only', 'Food order has a significant impact on postprandial glucose and insulin levels', 'peer-reviewed randomized crossover trial', 'https://pubmed.ncbi.nlm.nih.gov/26106234/', '2026-09-17', TRUE)
